'use client';
import { useEffect, useMemo, useState } from 'react';
import Link from 'next/link';
import StatusPill, { statusToneMap } from '@/components/ui/StatusPill';
import { ArrowUpRight, BarChart3, BriefcaseBusiness, CalendarDays, CheckCircle2, ChevronRight, Clock3, FolderOpen, IndianRupee, MapPin, MessageCircle, Plus, Sparkles, UploadCloud } from 'lucide-react';

const FLOW = ['requested','vendor_assigned','shoot_scheduled','shoot_completed','editing','preview','client_approved','delivered','closed'];
const FLOW_LABELS = { requested:'Requested', vendor_assigned:'Assigned', shoot_scheduled:'Scheduled', shoot_completed:'Shoot complete', editing:'Editing', preview:'Preview', client_approved:'Approved', delivered:'Delivered', closed:'Closed' };
function formatDate(d){ return d ? new Date(d).toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'}) : 'Date TBD'; }

export default function VendorDashboardPage(){
  const [projects,setProjects]=useState([]); const [vendor,setVendor]=useState(null);
  useEffect(()=>{ fetch('/api/projects').then(r=>r.json()).then(d=>setProjects(d.projects||[])); fetch('/api/vendor/profile').then(r=>r.json()).then(d=>setVendor(d.vendor)); },[]);
  const active=projects.filter(p=>!['delivered','closed'].includes(p.status));
  const completed=projects.filter(p=>['delivered','closed'].includes(p.status));
  const pending=projects.reduce((s,p)=>s+(p.amountPendingVendor||0),0);
  const scheduled=projects.filter(p=>p.status==='shoot_scheduled');
  const nextProject=useMemo(()=>[...active].sort((a,b)=>new Date(a.eventDate||'9999')-new Date(b.eventDate||'9999'))[0],[active]);
  const recent=projects.slice(0,5);
  return <div className="space-y-7">
    <section className="relative overflow-hidden rounded-[28px] bg-primary text-white p-7 sm:p-9 xl:p-10 shadow-[0_22px_60px_rgba(17,17,17,.12)]"><div className="absolute -right-20 -top-32 w-[430px] h-[430px] rounded-full bg-gold/15 blur-3xl"/><div className="absolute right-20 bottom-0 w-48 h-48 rounded-full border border-white/5"/><div className="relative grid xl:grid-cols-[1fr_auto] gap-8 items-end"><div><div className="flex items-center gap-2 text-gold text-[10px] uppercase tracking-[.24em] font-semibold"><Sparkles size={13}/> Partner command centre</div><h1 className="font-head text-3xl sm:text-4xl xl:text-5xl mt-3 tracking-[-.03em]">Welcome back{vendor?.firstName?`, ${vendor.firstName}`:''}.</h1><p className="text-white/55 text-sm mt-3 max-w-xl leading-6">Your Pikture Factory workspace for projects, delivery, finance and everything your team needs to keep shoots moving.</p></div><div className="grid grid-cols-2 gap-2 min-w-[250px]"><div className="rounded-2xl bg-white/[.07] border border-white/10 p-4"><span className="text-[10px] uppercase tracking-widest text-white/35">Vendor code</span><b className="block mt-1 text-lg">{vendor?.vendorCode||'—'}</b></div><div className="rounded-2xl bg-white/[.07] border border-white/10 p-4"><span className="text-[10px] uppercase tracking-widest text-white/35">Area</span><b className="block mt-1 text-sm truncate">{vendor?.location||'—'}</b></div></div></div></section>

    <section className="grid grid-cols-2 xl:grid-cols-4 gap-4 sm:gap-5">
      {[['Active projects',active.length,FolderOpen,'Projects currently in motion','text-primary'],['Scheduled shoots',scheduled.length,CalendarDays,'Upcoming assignments','text-primary'],['Completed',completed.length,CheckCircle2,'Delivered or closed','text-success'],['Finance due',`₹${pending.toLocaleString('en-IN')}`,IndianRupee,'Pending vendor payout','text-warning']].map(([label,value,Icon,sub,tone])=><div key={label} className="metric-card group hover:border-gold/50 transition-colors"><div className="flex items-start justify-between"><div className="w-10 h-10 rounded-xl bg-bglight flex items-center justify-center text-gold"><Icon size={18}/></div><ArrowUpRight size={15} className="text-border group-hover:text-gold transition-colors"/></div><b className={`font-head text-2xl sm:text-3xl block mt-5 ${tone}`}>{value}</b><span className="text-xs font-semibold block mt-1">{label}</span><span className="text-[11px] text-secondary">{sub}</span></div>)}
    </section>

    <section className="grid xl:grid-cols-[1.55fr_.75fr] gap-6">
      <div className="panel !p-0 overflow-hidden"><div className="px-5 sm:px-7 py-5 border-b border-border flex items-center justify-between"><div><span className="section-kicker">Live workflow</span><h2 className="font-head text-2xl mt-1">Your projects</h2></div><Link href="/vendor/data" className="btn btn-outline btn-sm">View data <BarChart3 size={14}/></Link></div><div className="divide-y divide-border">{recent.map(p=>{const tone=statusToneMap(p.status); const idx=Math.max(0,FLOW.indexOf(p.status)); const progress=Math.min(100,Math.round((idx/(FLOW.length-1))*100)); return <Link href={`/vendor/projects/${p._id}`} key={p._id} className="block px-5 sm:px-7 py-5 hover:bg-bglight/70 transition-colors"><div className="flex flex-col md:flex-row md:items-center gap-4"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className="text-[10px] font-bold tracking-widest text-gold">{p.projectCode}</span><StatusPill tone={tone.tone}>{tone.label}</StatusPill></div><h3 className="font-head text-xl mt-1 truncate">{p.eventType||'Event'} · {formatDate(p.eventDate)}</h3><p className="text-xs text-secondary mt-1 flex items-center gap-1.5"><MapPin size={12}/> {p.location||'Location pending'} <span>·</span><BriefcaseBusiness size={12}/> Project workspace</p></div><div className="w-full md:w-44"><div className="flex justify-between text-[10px] text-secondary mb-2"><span>Workflow</span><b>{progress}%</b></div><div className="h-1.5 rounded-full bg-border overflow-hidden"><div className="h-full bg-gold rounded-full" style={{width:`${progress}%`}}/></div><span className="text-[10px] text-secondary mt-2 block">{FLOW_LABELS[p.status]||p.status}</span></div><ChevronRight size={17} className="hidden md:block text-secondary"/></div></Link>})}{!recent.length&&<div className="py-16 text-center"><FolderOpen size={30} className="text-gold mx-auto mb-3"/><h3 className="font-head text-xl">No projects assigned yet</h3><p className="text-sm text-secondary mt-1">New assignments will appear here automatically.</p></div>}</div></div>
      <div className="space-y-6"><div className="panel bg-primary text-white border-primary"><span className="section-kicker">Next up</span><h2 className="font-head text-2xl mt-2">{nextProject?.eventType||'No upcoming shoot'}</h2>{nextProject?<><p className="text-white/50 text-xs mt-2">{formatDate(nextProject.eventDate)} · {nextProject.location||'Location pending'}</p><Link href={`/vendor/projects/${nextProject._id}`} className="btn btn-gold btn-sm mt-5">Open project <ArrowUpRight size={14}/></Link></>:<p className="text-white/50 text-xs mt-2">Your next assignment will appear here.</p>}</div><div className="panel"><div className="flex items-center gap-2 mb-4"><MessageCircle size={17} className="text-gold"/><div><span className="section-kicker">Admin updates</span><h3 className="font-head text-xl mt-0.5">Stay in the loop</h3></div></div><p className="text-xs text-secondary leading-5">Open any project to message the admin directly. Keep project-specific conversations attached to the work.</p><Link href={nextProject?`/vendor/projects/${nextProject._id}`:'/vendor/dashboard'} className="btn btn-outline btn-sm mt-5">{nextProject?'Message admin':'View workspace'}</Link></div></div>
    </section>

    <section><div className="flex items-end justify-between mb-4"><div><span className="section-kicker">Quick actions</span><h2 className="font-head text-2xl mt-1">Work faster</h2></div></div><div className="grid sm:grid-cols-3 gap-4"><Link href="/vendor/portfolio" className="panel group hover:border-gold/50 transition-colors"><div className="w-11 h-11 rounded-xl bg-gold/10 text-gold flex items-center justify-center"><UploadCloud size={19}/></div><h3 className="font-head text-lg mt-4">Update portfolio</h3><p className="text-xs text-secondary mt-1">Submit your strongest work for approval.</p><span className="inline-flex items-center gap-1 text-xs font-semibold mt-4">Open portfolio <ArrowUpRight size={13}/></span></Link><Link href="/vendor/payments" className="panel group hover:border-gold/50 transition-colors"><div className="w-11 h-11 rounded-xl bg-gold/10 text-gold flex items-center justify-center"><IndianRupee size={19}/></div><h3 className="font-head text-lg mt-4">Review finance</h3><p className="text-xs text-secondary mt-1">See received and pending payouts by project.</p><span className="inline-flex items-center gap-1 text-xs font-semibold mt-4">Open finance <ArrowUpRight size={13}/></span></Link><Link href="/vendor/data" className="panel group hover:border-gold/50 transition-colors"><div className="w-11 h-11 rounded-xl bg-gold/10 text-gold flex items-center justify-center"><BarChart3 size={19}/></div><h3 className="font-head text-lg mt-4">View your data</h3><p className="text-xs text-secondary mt-1">Understand workload, delivery and earnings trends.</p><span className="inline-flex items-center gap-1 text-xs font-semibold mt-4">View insights <ArrowUpRight size={13}/></span></Link></div></section>
  </div>;
}
